150	bool supportsIpVersion(const Address::IpVersion version) {
151	  Address::InstanceConstSharedPtr addr = getCanonicalLoopbackAddress(version);
152	  IoHandlePtr io_handle = addr->socket(Address::SocketType::Stream);
153	  if (0 != addr->bind(io_handle->fd()).rc_) {
154	    // Socket bind failed.
155	    RELEASE_ASSERT(io_handle->close().err_ == nullptr, "");
156	    return false;
157	  }
158	  RELEASE_ASSERT(io_handle->close().err_ == nullptr, "");
159	  return true;
