73	void UdpStatsdSink::onHistogramComplete(const Stats::Histogram& histogram, uint64_t value) {
74	  // For statsd histograms are all timers in milliseconds, Envoy histograms are however
75	  // not necessarily timers in milliseconds, for Envoy histograms suffixed with their corresponding
76	  // SI unit symbol this is acceptable, but for histograms without a suffix, especially those which
77	  // are timers but record in units other than milliseconds, it may make sense to scale the value to
78	  // milliseconds here and potentially suffix the names accordingly (minus the pre-existing ones for
79	  // backwards compatibility).
80	  const std::string message(absl::StrCat(prefix_, ".", getName(histogram), ":",
81	                                         std::chrono::milliseconds(value).count(), "|ms",
82	                                         buildTagStr(histogram.tags())));
83	  tls_->getTyped<Writer>().write(message);
84	}
