94	const std::string UdpStatsdSink::buildTagStr(const std::vector<Stats::Tag>& tags) const {
95	  if (!use_tag_ || tags.empty()) {
96	    return "";
97	  }
98	
99	  std::vector<std::string> tag_strings;
100	  tag_strings.reserve(tags.size());
101	  for (const Stats::Tag& tag : tags) {
102	    tag_strings.emplace_back(tag.name_ + ":" + tag.value_);
103	  }
104	  return "|#" + absl::StrJoin(tag_strings, ",");
105	}
