154	void TcpStatsdSink::TlsSink::commonFlush(const std::string& name, uint64_t value, char stat_type) {
155	  ASSERT(current_slice_mem_ != nullptr);
156	  // 36 > 1 ("." after prefix) + 1 (":" after name) + 4 (postfix chars, e.g., "|ms\n") + 30 for
157	  // number (bigger than it will ever be)
158	  const uint32_t max_size = name.size() + parent_.getPrefix().size() + 36;
159	  if (current_buffer_slice_.len_ - usedBuffer() < max_size) {
160	    endFlush(false);
161	    beginFlush(false);
162	  }
163	
164	  // Produces something like "envoy.{}:{}|c\n"
165	  // This written this way for maximum perf since with a large number of stats and at a high flush
166	  // rate this can become expensive.
167	  const char* snapped_current = current_slice_mem_;
168	  memcpy(current_slice_mem_, parent_.getPrefix().c_str(), parent_.getPrefix().size());
169	  current_slice_mem_ += parent_.getPrefix().size();
170	  *current_slice_mem_++ = '.';
171	  memcpy(current_slice_mem_, name.c_str(), name.size());
172	  current_slice_mem_ += name.size();
173	  *current_slice_mem_++ = ':';
174	  current_slice_mem_ += StringUtil::itoa(current_slice_mem_, 30, value);
175	  *current_slice_mem_++ = '|';
176	  *current_slice_mem_++ = stat_type;
177	  *current_slice_mem_++ = '\n';
178	
179	  ASSERT(static_cast<uint64_t>(current_slice_mem_ - snapped_current) < max_size);
180	}
